    function applyFilters() {
      if (!allPosts.length) return;
      const searchTerm = searchInput.value.trim().toLowerCase();
    
      // Filter only by title from already fetched posts
      const filteredPosts = allPosts.filter(post =>
        (post.title || '').toLowerCase().includes(searchTerm)
      );
    
      renderCards(filteredPosts);
    }

    // Server-side fetch on dropdown change
    countryFilter.addEventListener("change", fetchPosts);
    cuisineFilter.addEventListener("change", fetchPosts);
    
    // Client-side search on input
    searchInput.addEventListener("input", applyFilters);

    // Initial load
    fetchDropdownOptions();
    fetchPosts();
